    function run(uint128 price, address outsider) public {
        require(outsider != address(this));
        // this contract is a ward (deployer), so authorized update succeeds
        c.updatePrice(price);
        uint128 afterAuth = c.latestPrice();
        assert(afterAuth == price);
        // non-authorized account cannot update the price
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.updatePrice.selector, uint128(1)));
        // ^ called from this contract, still authorized; instead verify outsider path via revert check
        // forge-style low-level check of a non-ward caller is not possible directly;
        // use the wards getter to express the authorization rule generally:
        uint256 outsiderWard = c.wards(outsider);
        assert(outsiderWard == 0);
        // rule: price remains exactly what was set, and lastPriceUpdate reflects the update
        assert(c.latestPrice() == price);
        assert(c.lastPriceUpdate() > 0);
    }
    receive() external payable {}
}

